const toggle=document.querySelector('#toggle'),menu=document.querySelector('#menu');toggle.addEventListener('click',()=>{const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');}));const dialog=document.querySelector('#lightbox');document.querySelectorAll('.gallery-item').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#expanded').src=button.dataset.src;document.querySelector('#expanded').alt=button.dataset.alt;document.querySelector('#caption').textContent=button.dataset.alt;dialog.showModal();}));document.querySelector('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
